{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C10"],
      "claim": "I-ketanserin, a 4-fluorobenzoyl piperidine, showed rapid and sustained brain uptake in baboon PET, directly supporting CNS access for the query's 4-substituted benzoyl piperidine core.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "[18F]altanserin, another 4-fluorobenzoyl piperidine, showed sufficient brain uptake in rat micro-PET, confirming that this scaffold can cross the BBB.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "[18F]FBMV, a vesamicol-like molecule with a 4-fluorobenzamide and hydroxy-substituted piperidine/cyclohexanol motif, showed desirable brain uptake in pig PET, supporting the query's hydroxytetralin-piperidine combination.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "The 4-fluorobenzoyl piperidine ester BMP showed extremely high brain uptake (>14% ID/g) in mice, demonstrating robust CNS penetration for this benzoyl piperidine class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "A 1-benzyl-4-piperidinyl benzamide showed significant and lasting high brain uptake in mice, supporting CNS access for lipophilic piperidine aryl-ketone/amide scaffolds.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "R-licarbazepine showed a brain/plasma ratio of 0.05-0.50 in mice, indicating restricted CNS entry, but its neutral carbamazepine-like scaffold is structurally distant from the query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a lipophilic 4-substituted benzoyl piperidine with a hydroxytetralin N-substituent; multiple close benzoyl piperidine PET tracers show robust brain uptake across species, outweighing distant low-similarity impermeable examples. Prediction: pass.",
  "evidence_gaps": [
    "No direct brain/plasma or CSF measurement for the exact query molecule",
    "No P-gp/BCRP efflux data for the query",
    "Morgan similarities to direct CNS PET evidence are moderate (0.22-0.32)",
    "Species differences in BBB properties between rodents, pigs, baboons, and humans"
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

